<?php
$todayIncome=(float)db()->query("SELECT COALESCE(SUM(amount),0) FROM payments WHERE DATE(payment_date)=CURDATE() AND status='completed'")->fetchColumn();
$monthIncome=(float)db()->query("SELECT COALESCE(SUM(amount),0) FROM payments WHERE YEAR(payment_date)=YEAR(CURDATE()) AND MONTH(payment_date)=MONTH(CURDATE()) AND status='completed'")->fetchColumn();
$clients=(int)db()->query('SELECT COUNT(*) FROM clients WHERE active=1')->fetchColumn();
$active=(int)db()->query("SELECT COUNT(*) FROM memberships WHERE status='active' AND end_date>=CURDATE()")->fetchColumn();
$due=(int)db()->query("SELECT COUNT(*) FROM memberships WHERE status='active' AND end_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 7 DAY)")->fetchColumn();
$recent=db()->query("SELECT p.*,c.name client_name FROM payments p JOIN clients c ON c.id=p.client_id WHERE p.status='completed' ORDER BY p.payment_date DESC,p.id DESC LIMIT 6")->fetchAll();
$monthly=db()->query("SELECT DATE_FORMAT(payment_date,'%b') label, SUM(amount) total, MONTH(payment_date) m FROM payments WHERE status='completed' AND payment_date>=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY YEAR(payment_date),MONTH(payment_date) ORDER BY YEAR(payment_date),MONTH(payment_date)")->fetchAll(); $max=max(array_map(fn($x)=>(float)$x['total'],$monthly)?:[1]);
?>
<div class="grid stats"><article class="card stat"><div class="stat-top"><span>Clientes registrados</span><span class="stat-icon">♙</span></div><div class="stat-value"><?=$clients?></div><div class="stat-foot">Perfiles activos en el sistema</div></article><article class="card stat"><div class="stat-top"><span>Membresías vigentes</span><span class="stat-icon">◉</span></div><div class="stat-value"><?=$active?></div><div class="stat-foot"><?=$due?> vencen en los próximos 7 días</div></article><article class="card stat"><div class="stat-top"><span>Ingresos del mes</span><span class="stat-icon">＄</span></div><div class="stat-value" style="font-size:22px"><?=money($monthIncome)?></div><div class="stat-foot">Recaudado durante este mes</div></article><article class="card stat"><div class="stat-top"><span>Ingresos de hoy</span><span class="stat-icon">↗</span></div><div class="stat-value" style="font-size:22px"><?=money($todayIncome)?></div><div class="stat-foot">Pagos registrados hoy</div></article></div>
<div class="grid cols"><section class="card panel"><div class="panel-head"><h2>Ingresos recientes</h2><a class="link-btn" href="index.php?view=payments">Ver pagos →</a></div><div class="table-wrap"><table><thead><tr><th>CLIENTE</th><th>FECHA</th><th>MÉTODO</th><th>MONTO</th></tr></thead><tbody><?php foreach($recent as $r): ?><tr><td><div class="person"><span class="mini-avatar"><?=h(mb_substr($r['client_name'],0,1))?></span><?=h($r['client_name'])?></div></td><td><?=date('d/m/Y',strtotime($r['payment_date']))?></td><td><?=h(ucfirst($r['method']))?></td><td><b><?=money($r['amount'])?></b></td></tr><?php endforeach; ?><?php if(!$recent): ?><tr><td colspan="4" class="empty">Aún no hay pagos registrados.</td></tr><?php endif; ?></tbody></table></div></section><div><section class="card panel"><div class="panel-head"><h2>Ingresos por mes</h2><small>Últimos meses · Bs</small></div><div class="bars"><?php foreach($monthly as $bar): ?><div class="bar-col"><span class="bar-amount"><?=number_format((float)$bar['total'],0)?></span><div class="bar <?=$bar['m']===(int)date('n')?'current':''?>" style="height:<?=max(4,((float)$bar['total']/$max)*70)?>%"></div><span><?=h($bar['label'])?></span></div><?php endforeach; ?><?php if(!$monthly): ?><div class="empty">Los ingresos aparecerán aquí.</div><?php endif; ?></div></section><section class="membership-highlight"><span class="eyebrow">PANEL MUTATIO</span><h2>Accesos rápidos</h2><p>Gestiona la operación diaria del gimnasio.</p><div class="actions"><a class="btn primary" href="index.php?view=attendance">Marcar asistencia</a><a class="btn" href="index.php?view=assistant">Preguntar al asistente</a></div></section></div></div>
